function translate(){document.documentElement.lang=lang==='vi'?'vi':'zh-Hant';$$('[data-i]').forEach(e=>e.textContent=t(e.dataset.i));$('#language').value=lang;setPage(current,false)}
function setPage(page,render=true){current=['daily','stats','history','feed','weights','settings'].includes(page)?page:'daily';$$('.page').forEach(e=>e.hidden=e.id!=='page-'+current);$$('nav a').forEach(e=>e.classList.toggle('active',e.dataset.page===current));$('#page-title').textContent=t(current);$('#page-subtitle').textContent=t(current+'Sub');$('#today').textContent=today();if(render&&data)renderCurrent()}
function conditional(){
 const movement=$('#movement-form'),delivery=$('#delivery-form'),usage=$('#usage-form'),weight=$('#weight-form');
 movement.querySelector('.outgoing-destination').hidden=!['sale','cull'].includes(val(movement,'type'));
 const transfer=val(movement,'type')==='transfer';movement.querySelector('.transfer-fields').hidden=!transfer;movement.elements.target_batch_id.required=transfer;
 const mode=val(delivery,'allocation_mode');delivery.querySelector('.delivery-scope').hidden=mode!=='single';delivery.querySelector('.multiple-fields').hidden=mode!=='multiple';delivery.querySelectorAll('.scope select').forEach(e=>e.required=mode==='single');
 const direct=val(usage,'method')==='direct';usage.querySelector('.direct-fields').hidden=!direct;usage.querySelector('.inventory-fields').hidden=direct;usage.elements.kg.required=direct;usage.elements.opening.required=!direct;usage.elements.closing.required=!direct;
 const individual=val(weight,'weight_mode')==='individual';weight.querySelectorAll('.total-fields').forEach(e=>e.hidden=individual);weight.querySelector('.individual-fields').hidden=!individual;weight.elements.count.required=!individual;weight.elements.total_kg.required=!individual;weight.elements.individual_kg.required=individual;
}
async function api(path,options={}){
 const headers={'Content-Type':'application/json',...(me?{'X-CSRF-Token':me.csrf}:{}),...options.headers};
 let response;try{response=await fetch(path,{...options,headers,cache:'no-store'})}catch(e){throw {error:'network',ambiguous:true}}
 let body;try{body=await response.json()}catch(e){throw {error:'network',ambiguous:true}}
 if(!response.ok){if(response.status===401&&me){$('#login-view').hidden=false;$('#workspace').hidden=true}throw {...body,status:response.status,ambiguous:response.status>=500}}
 return body;
}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,2600)}
function messageError(e){return t(e.error||'network')+(e.error==='overlapping_usage'&&e.details?'\n'+e.details.join(', '):'')}
function persistPending(){if(pending)localStorage.setItem('pig-pending',JSON.stringify(pending));else localStorage.removeItem('pig-pending');$('#pending').hidden=!pending;$$('form[data-kind]').forEach(f=>{const restricted=me?.role==='viewer'||(['barns','batches'].includes(f.dataset.kind)&&me?.role!=='admin');f.querySelectorAll('input,select,textarea').forEach(e=>e.disabled=restricted||pending?.formId===f.id);if(f.id==='usage-form'&&me?.role!=='admin')f.elements.active.disabled=true;f.querySelector('.primary').disabled=!!pending||restricted;f.querySelector('[data-action=cancelEdit]').disabled=pending?.formId===f.id})}
function startWrite(path,method,body,formId=null){if(pending){toast(t('pending'));return}pending={path,method,body,key:crypto.randomUUID(),user:me.id,formId};persistPending();return retryPending()}
async function retryPending(){
 if(!pending||retryPending.busy)return;
 if(pending.user!==me?.id){toast(t('login_required'));return}
 retryPending.busy=true;$('#retry').disabled=true;
 const request=pending;
 try{
  const result=await api(request.path,{method:request.method,body:JSON.stringify(request.body),headers:{'Idempotency-Key':request.key}});
  pending=null;persistPending();
  if(request.formId){const f=$('#'+request.formId);finishForm(f);f.querySelector('.form-error').textContent=''}
  toast(t('saved'));if(result.sync&&result.sync.version===VERSION){data=result.sync;selections();await renderCurrent()}else await refresh();
  if(request.path==='/api/weighings'||/^\/api\/weights(?:\/|$)/.test(request.path))document.dispatchEvent(new CustomEvent('pigledger:weighing-saved',{detail:{session_id:result.session_id||null,id:result.id||null}}));
 }catch(e){
  if(request.formId)$('#'+request.formId).querySelector('.form-error').textContent=messageError(e);else toast(messageError(e));
  if(!e.ambiguous){pending=null;persistPending()}
 }finally{retryPending.busy=false;$('#retry').disabled=false}
}
function finishForm(f){
 const wasEdit=!!f.dataset.editId;
 if(f.id==='batch-form'){f.elements.entry_count.readOnly=false;f.elements.entry_count.required=true;f.elements.entry_date.readOnly=false;}
 for(const name of ['quantity','note','outgoing_destination','total_weight_kg','amount','kg','opening','closing','count','total_kg','individual_kg','sampling','pen','age_days','name','entry_count','entry_age']){if(f.elements.namedItem(name))f.elements.namedItem(name).value=''}
 for(const name of ['transfer_in','transfer_out','loss'])if(f.elements.namedItem(name))f.elements.namedItem(name).value='0';
 if(f.id==='delivery-form')$('#allocation-rows').replaceChildren();
 if(f.id==='weight-form')f.elements.representative.checked=false;
 delete f.dataset.editId;delete f.dataset.revision;delete f.dataset.dirty;
 f.querySelector('[data-action=cancelEdit]').hidden=true;f.querySelector('.edit-label').hidden=true;
 if(wasEdit){if(f.elements.namedItem('active'))f.elements.active.checked=true}
}
function collect(f){
 const d=Object.fromEntries(new FormData(f));delete d.barn_id;
 if(f.id==='movement-form'&&!['sale','cull'].includes(d.type))delete d.outgoing_destination;
 for(const k of ['quantity','total_weight_kg','kg','opening','closing','transfer_in','transfer_out','loss','count','total_kg','age_days','entry_count'])if(k in d)d[k]=d[k]===''?null:Number(d[k]);
 if(f.id==='delivery-form'){
  d.kg=Number(d.amount)*(d.display_unit==='ton'?1000:1);
  d.allocations=d.allocation_mode==='common'?[]:d.allocation_mode==='single'?[{batch_id:d.batch_id,kg:d.kg}]:$$('#allocation-rows .allocation-row').map(row=>({batch_id:row.querySelector('select').value,kg:Number(row.querySelector('input').value)}));
  delete d.amount;delete d.batch_id;delete d.allocation_mode;
 }
 if(f.id==='usage-form'){d.active=f.elements.active.checked;if(d.method==='direct'){for(const k of ['opening','closing','transfer_in','transfer_out','loss'])delete d[k]}else delete d.kg}
 if(f.id==='weight-form'){d.representative=f.elements.representative.checked;if(d.weight_mode==='individual'){d.individual_kg=d.individual_kg.trim().split(/[\s,，;]+/).filter(Boolean).map(Number);delete d.count;delete d.total_kg}else d.individual_kg=[];delete d.weight_mode}
 if(f.id==='batch-form'){d.barn_id=val(f,'barn_id');d.entry_age_days=d.entry_age===''?null:Number(d.entry_age)*(d.age_unit==='weeks'?7:1);delete d.entry_age;delete d.age_unit;if(!d.age_date)delete d.age_date}
 if(f.dataset.editId)d.revision=Number(f.dataset.revision);
 if(f.id==='batch-form'&&f.dataset.editId){const original=data.batches.find(b=>b.id===f.dataset.editId);if(original?.legacy_source){for(const key of ['legacy_source','legacy_row','legacy_barn','note'])d[key]=original[key];}}
 return d;
}
function saveForm(e){e.preventDefault();const f=e.target;if(!f.reportValidity())return;f.querySelector('.form-error').textContent='';startWrite('/api/'+f.dataset.kind+(f.dataset.editId?'/'+f.dataset.editId:''),f.dataset.editId?'PUT':'POST',collect(f),f.id)}
function batchName(id){const b=data.batches.find(b=>b.id===id);return b?`${data.barns.find(x=>x.id===b.barn_id)?.name||''} · ${b.name}`:t('unassigned')}
function replaceOptions(el,html,defaultValue=''){const old=el.value;el.innerHTML=html;el.value=Array.from(el.options).some(o=>o.value===old)?old:defaultValue}
function updateScope(scope,auto=false){
 if(!data)return;const barn=scope.querySelector('[name=barn_id]'),batch=scope.querySelector('[name=batch_id]');
 const available=data.batches.filter(b=>b.barn_id===barn.value&&(b.status==='active'||me.role==='admin'));
 const old=batch.value;if(!auto&&old&&!available.some(b=>b.id===old)){const selected=data.batches.find(b=>b.id===old&&b.barn_id===barn.value);if(selected)available.push(selected)}replaceOptions(batch,option('','choose')+available.map(b=>`<option value="${b.id}">${esc(b.name)}${b.status==='ended'?' · '+t('ended'):''}</option>`).join(''));
 if(auto){batch.value=available.filter(b=>b.status==='active').length===1?available.find(b=>b.status==='active').id:''}
}
function updateFilterBatch(f,reset=false){const el=f.elements.batch_id;if(!el)return;const old=el.value;replaceOptions(el,option('','all')+data.batches.filter(b=>!val(f,'barn_id')||b.barn_id===val(f,'barn_id')).map(b=>`<option value="${b.id}">${esc(batchName(b.id))}</option>`).join(''));if(reset&&old&&!Array.from(el.options).some(o=>o.value===old))el.value=''}
function selections(force=false){
 const fp=JSON.stringify([data.barns,data.batches,lang,me.role]);if(!force&&fp===selectionFingerprint)return;selectionFingerprint=fp;
 $$('select[name=barn_id]').forEach(el=>replaceOptions(el,option('',el.closest('.filters')?'all':'choose')+data.barns.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')));
 $$('.scope').forEach(s=>updateScope(s,!selectionFingerprint));$$('.filters').forEach(f=>updateFilterBatch(f));
 const groups=[...new Set(data.batches.map(b=>(b.group!==b.name?b.group:'')||data.barns.find(x=>x.id===b.barn_id)?.group).filter(Boolean))];$$('.filters select[name=group]').forEach(el=>replaceOptions(el,option('','all')+groups.map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')));
 replaceOptions($('#movement-form [name=target_batch_id]'),option('','choose')+data.batches.filter(b=>b.status==='active'||me.role==='admin').map(b=>`<option value="${b.id}">${esc(batchName(b.id))}</option>`).join(''));
 replaceOptions($('#batch-form [name=cohort_id]'),option('','choose')+data.batches.filter(b=>!b.cohort_id).map(b=>`<option value="${b.id}">${esc(batchName(b.id))}</option>`).join(''));
 $$('#allocation-rows select').forEach(el=>replaceOptions(el,allocationOptions()));
 const isAdmin=me.role==='admin';$$('.admin-section').forEach(e=>e.hidden=!isAdmin);$('#admin-info').hidden=isAdmin;
 $$('form[data-kind]').forEach(f=>{const restricted=me.role==='viewer'||(['barns','batches'].includes(f.dataset.kind)&&!isAdmin);f.querySelectorAll('input,select,textarea,button').forEach(e=>e.disabled=restricted)});
 $('#movement-form [value=adjustment]').disabled=!isAdmin;
 $('#usage-form [name=active]').disabled=!isAdmin;
 if(me.role==='viewer')$('#page-subtitle').textContent=t('readOnly');persistPending();
}
function allocationOptions(){return option('','choose')+data.batches.map(b=>`<option value="${b.id}">${esc(batchName(b.id))}</option>`).join('')}
function allocationRow(a={}){const row=document.createElement('div');row.className='allocation-row';row.innerHTML=`<select aria-label="${esc(t('batch'))}">${allocationOptions()}</select><input aria-label="${esc(t('kg'))}" type="number" min="0.000001" step="any" required><button type="button" aria-label="${esc(t('delete'))}">×</button>`;row.querySelector('select').value=a.batch_id||'';row.querySelector('input').value=a.kg??'';row.querySelector('button').onclick=()=>row.remove();$('#allocation-rows').append(row)}
let sharedFilters={};try{sharedFilters=JSON.parse(localStorage.getItem('pig-filters')||'{}')}catch(e){}
function syncFilters(source){for(const k of ['from','to','barn_id','batch_id'])sharedFilters[k]=val(source,k);localStorage.setItem('pig-filters',JSON.stringify(sharedFilters));$$('.filters').forEach(f=>{if(f!==source){for(const k of ['from','to','barn_id'])f.elements[k].value=sharedFilters[k]||'';updateFilterBatch(f);f.elements.batch_id.value=sharedFilters.batch_id||''}})}
function query(f){const p=new URLSearchParams();for(const k of ['from','to','barn_id','batch_id','group','type','vendor','item'])if(val(f,k))p.set(k,val(f,k));return p.toString()}
function metric(key,value,sub,feature=false){return `<div class="metric ${feature?'feature':''}" data-metric="${esc(key)}"><div class="label">${esc(t(key))}</div><span class="value">${value}</span><small>${esc(sub)}</small></div>`}
function empty(){return `<div class="empty">${esc(t('noRecords'))}</div>`}
function recordActions(kind,r){if(kind==='movements'&&r.legacy_source)return esc(t('legacyReadonly'));return me.role==='admin'?`<button data-edit="${kind}" data-id="${r.id}">${esc(t('edit'))}</button><button class="danger" data-delete="${kind}" data-id="${r.id}">${esc(t('delete'))}</button>`:''}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(k=>`<th>${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function rowsHTML(kind,rows){if(!rows.length)return empty();
 if(kind==='movements')return table(['date','batch','type','quantity','note','edit'],rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.legacy_batch||batchName(r.batch_id))}${r.legacy_source&&!r.batch_id?'<br>'+esc(t('unassigned')):''}${r.target_batch_id?'<br>→ '+esc(batchName(r.target_batch_id)):''}</td><td>${esc(t(r.type))}</td><td>${fmt(r.quantity,0)}</td><td>${esc(r.note)}</td><td>${recordActions(kind,r)}</td></tr>`));
 if(kind==='deliveries')return table(['date','batch','amount','vendor','item','note','edit'],rows.map(r=>`<tr><td>${r.date}</td><td>${r.allocations.length?r.allocations.map(a=>esc(batchName(a.batch_id))+': '+fmt(a.kg)+' kg').join('<br>'):esc(t('unallocated'))}</td><td>${fmt(r.display_unit==='ton'?r.kg/1000:r.kg)} ${esc(t(r.display_unit))}</td><td>${esc(r.vendor)}</td><td>${esc(r.item)}</td><td>${esc(r.note)}</td><td>${recordActions(kind,r)}</td></tr>`));
 if(kind==='usages')return table(['from','endExclusive','batch','source','consumed','status','edit'],rows.map(r=>`<tr><td>${r.start}</td><td>${r.end}</td><td>${esc(batchName(r.batch_id))}</td><td>${esc(t(r.method))}<br>${esc(r.note)}</td><td class="${r.computed_kg<0?'warning-text':''}">${fmt(r.computed_kg)}${r.computed_kg<0?'<br>'+esc(t('anomaly')):''}</td><td>${esc(t(r.active?'adopted':'excluded'))}</td><td>${recordActions(kind,r)}</td></tr>`));
 if(kind==='weights')return table(['date','batch','pen','weightCount','totalWeight','mean','age','edit'],rows.map(r=>`<tr><td>${r.date}</td><td>${esc(batchName(r.batch_id))}</td><td>${esc(r.pen)}<br><small>${esc(r.sampling)}</small></td><td>${fmt(r.count,0)}</td><td>${fmtWeight(r.total_kg)}</td><td>${fmtWeight(r.total_kg/r.count)}</td><td>${fmt(r.age_days)}<br><small>${esc(r.note)}</small></td><td>${recordActions(kind,r)}</td></tr>`));
 return '';
}
function displayAge(days){return days==null?t('ageUnknown'):`${fmt(Math.floor(days/7),0)} ${t('week')} ${fmt(days%7,0)} ${t('days')}`}
function preserveBox(id,html){const el=$('#'+id);if(el.contains(document.activeElement))return;const open=new Set(Array.from(el.querySelectorAll('details[open][data-key]')).map(d=>d.dataset.key));el.innerHTML=html;el.querySelectorAll('details[data-key]').forEach(d=>d.open=open.has(d.dataset.key))}
async function renderHome(){const snapshot=data,s=data.dashboard?.as_of===today()?data.dashboard:await api('/api/statistics?summary=1&to='+today());if(data===snapshot)data.dashboard=s;const c=s.cumulative;
 let sourceNote=$('#home-legacy-note');if(!sourceNote){sourceNote=document.createElement('details');sourceNote.id='home-legacy-note';sourceNote.innerHTML='<summary></summary><p class="note"></p>';$('#home-metrics').before(sourceNote)}sourceNote.hidden=!data.workbooks?.length;sourceNote.querySelector('summary').textContent=t('sourceDisclosure');sourceNote.querySelector('p').textContent=t('legacyHint');
 $('#home-metrics').innerHTML=metric('remaining',fmt(c.remaining,0),t('heads'),true)+metric('outgoing',fmt(c.outgoing,0),t('saleAndCull'))+metric('dead',fmt(c.dead,0),t('asOf')+' '+today())+metric('survival',(c.survival==null?'—':fmt(c.survival)+'%'),t('deathOnly'));
 $('#barns').innerHTML=data.barns.length?data.barns.map(b=>{const batches=data.batches.filter(x=>x.barn_id===b.id&&x.status==='active');const results=batches.map(x=>s.batches.find(y=>y.id===x.id)).filter(Boolean);return `<article class="barn-card"><div class="barn-top"><h3>${esc(b.name)}</h3><span class="pill">${esc(b.group||t('active'))}</span></div><div class="big">${fmt(results.some(x=>x.herd.remaining==null)?null:results.reduce((sum,x)=>sum+x.herd.remaining,0),0)} <small>${t('heads')}</small></div>${batches.length?batches.map(x=>{const result=s.batches.find(y=>y.id===x.id);return `<div class="batch-line"><small>${esc(x.name)}</small><small>${esc(displayAge(result?.age_days))}</small></div>`}).join(''):`<p class="hint">${t('noActive')}</p>`}<button data-add-barn="${b.id}">${esc(t('addRecord'))}</button></article>`}).join(''):`<div class="empty">${t('emptyBarns')}</div>`;
 $('#recent').innerHTML=[...data.movements].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(r=>`<article class="recent-row"><div class="section-row"><strong>${esc(t(r.type))} · ${fmt(r.quantity,0)} ${t('heads')}</strong><small>${r.date}</small></div><small>${esc(batchName(r.batch_id))}</small>${movementNote(r)?'<p class="hint">'+esc(movementNote(r))+'</p>':''}<div class="recent-actions">${recordActions('movements',r)}</div></article>`).join('')||empty();
 return s;
}
function statHTML(s){const c=s.cumulative;let html=`<h2 class="section-row">${t('asOf')} · ${esc(s.as_of)}</h2><div class="metrics">${metric('remaining',fmt(c.remaining,0),t('heads'),true)}${metric('outgoing',fmt(c.outgoing,0),t('saleAndCull'))}${metric('dead',fmt(c.dead,0),t('heads'))}${metric('survival',c.survival==null?'—':(c.survival==null?'—':fmt(c.survival)+'%'),t('deathOnly'))}</div><div class="card">${table(['entry','added','cull','sale','transferIn','transferOut','adjusted','denominator'],[`<tr>${['entry','added','culled','sold','transfer_in','transfer_out','adjustment','denominator'].map(k=>`<td>${fmt(c[k],0)}</td>`).join('')}</tr>`])}<p class="hint">${t('denominatorHint')}</p></div>`;
 if(s.interval)html+=`<div class="card"><h2>${t('interval')} · ${esc(val($('#stats-filter'),'from'))} → ${s.as_of}</h2>${table(['entry','sale','cull','death','added','transferIn','transferOut','adjusted'],[`<tr>${['entry','sale','cull','death','arrival','transfer_in','transfer_out','adjustment'].map(k=>`<td>${fmt(s.interval[k],0)}</td>`).join('')}</tr>`])}</div>`;
 html+=`<div class="card"><h2>${t('feed')}</h2><div class="performance"><div>${t('orderTotal')}<strong>${fmt(s.feed_order_kg)}</strong></div><div>${t('delivered')}<strong>${fmt(s.delivery_kg)}</strong></div><div>${t('consumed')}<strong>${fmt(s.consumption_kg)}</strong></div><div>${t('unallocated')}<strong>${fmt(s.unallocated_kg)}</strong></div></div><p class="hint">${t('feedPartial')} · ${t('excludedUsage')}: ${s.excluded_usage_count}</p>${s.negative_usage?'<p class="warning-text">'+t('anomaly')+'</p>':''}</div><div class="card"><h2>${t('fcr')}</h2><strong>${s.aggregate_fcr==null?t('insufficient'):fmt(s.aggregate_fcr)}</strong>${s.fcr_period?'<p>'+s.fcr_period.join(' → ')+'</p>':''}<p class="hint">${t('aggregateHint')}</p><p class="hint">${t('fcrMethod')}</p></div><div class="card"><h2>${t('batchDetails')}</h2>${s.batches.map(b=>perfHTML(b)).join('')||empty()}</div>`;return html;
}
function perfHTML(b){const p=b.performance;return `<details data-key="${b.id}"><summary>${esc(batchName(b.id))} · ${t('remaining')} ${fmt(b.herd.remaining,0)} · ${esc(displayAge(b.age_days))}</summary><div class="performance"><div>${t('mean')}<strong>${p.last?fmt(p.last.mean):'—'}</strong><small>${p.last?.date||'—'} · ${t('sample')}</small></div><div>${t('adg')}<strong>${fmt(p.adg)}</strong><small>${t('kgPerDay')}</small></div><div>${t('estimatedFcr')}<strong>${fmt(p.fcr)}</strong><small>${p.fcr==null?(p.reasons.includes('empty_fcr_period')?t('empty_fcr_period'):t('insufficient')):t('fcrSentence')+' '+fmt(p.fcr)+' '+t('feedKg')}</small></div></div>${p.first?`<p class="hint">${t('comparison')}: ${p.first.date} → ${p.last.date} (${p.days} ${t('days')})<br>${fmt(p.first.mean)} → ${fmt(p.last.mean)} kg · ${t('gainPerPig')}: ${fmt(p.delta)}<br>${t('consumed')}: ${fmt(p.feed)} · ${t('gain')}: ${fmt(p.gain)}</p>`:''}${p.composition_changed?'<p class="note">'+t('composition')+'</p>':''}${p.reasons.length?'<p class="warning-text hint">'+p.reasons.map(k=>esc(t(k))).join(' · ')+'</p>':''}</details>`}
function calcConsumption(u){if(u.method==='direct')return u.kg;return u.opening+data.deliveries.filter(d=>u.start<=d.date&&d.date<u.end&&(!u.vendor||d.vendor===u.vendor)&&(!u.item||d.item===u.item)).reduce((n,d)=>n+d.allocations.filter(a=>a.batch_id===u.batch_id).reduce((n,a)=>n+a.kg,0),0)+u.transfer_in-u.closing-u.transfer_out-u.loss}
let renderTicket=0;
async function renderCurrent(){
 const ticket=++renderTicket,page=current;
 try{
  if(page==='daily')await renderHome();
  if(page==='stats'){const result=await api('/api/statistics?'+query($('#stats-filter'))+(!val($('#stats-filter'),'to')?'&to='+today():''));if(ticket===renderTicket)preserveBox('stats-results',(result.cumulative.historical_unknown||result.legacy_interval_unknown?'<p class="note">'+esc(t('sourceRangeUnknown'))+'</p>':'')+statHTML(result))}
  if(page==='history'){const rows=await api('/api/movements?'+query($('#history-filter')));if(ticket===renderTicket)$('#history-results').innerHTML=rowsHTML('movements',rows)}
  if(page==='feed'){const q=query($('#feed-filter'));const [deliveries,usages]=await Promise.all([api('/api/deliveries?'+q),api('/api/usages?'+q)]);if(ticket===renderTicket){$('#delivery-results').innerHTML=rowsHTML('deliveries',deliveries);$('#usage-results').innerHTML=rowsHTML('usages',usages.map(u=>({...u,computed_kg:calcConsumption(u)})))}}
  if(page==='weights'){const rows=await api('/api/weights?'+query($('#weight-filter')));if(ticket===renderTicket){$('#weight-results').innerHTML=rowsHTML('weights',rows);const grouped={};rows.forEach(r=>{const k=r.batch_id+'|'+r.date;const g=grouped[k]||={date:r.date,batch_id:r.batch_id,count:0,total:0};g.count+=r.count;g.total+=r.total_kg});const summary=Object.values(grouped).length?table(['date','batch','weightCount','mean'],Object.values(grouped).map(g=>`<tr><td>${g.date}</td><td>${esc(batchName(g.batch_id))}</td><td>${fmt(g.count,0)}</td><td>${fmtWeight(g.total/g.count)}</td></tr>`)):'';preserveBox('weight-summary',summary+sampleSummary(rows))}}
  if(page==='settings')renderSettings();
 }catch(e){toast(messageError(e))}
}

function sampleSummary(rows){
 if(!rows.length)return '';
 const byDate={},pens={};
 for(const r of rows){const day=byDate[r.date]||={count:0,total:0};day.count+=r.count;day.total+=r.total_kg;const key=r.batch_id+'|'+r.date+'|'+(r.pen||'—');const p=pens[key]||={date:r.date,batch_id:r.batch_id,pen:r.pen||'—',count:0,total:0};p.count+=r.count;p.total+=r.total_kg}
 return `<h3>${t('mergedSamples')}</h3>${table(['date','weightCount','mean'],Object.entries(byDate).map(([date,r])=>`<tr><td>${date}</td><td>${fmt(r.count,0)}</td><td>${fmtWeight(r.total/r.count)}</td></tr>`))}<p class="hint">${t('sampleHint')}</p><details data-key="pens"><summary>${t('penSamples')}</summary>${table(['date','batch','pen','weightCount','mean'],Object.values(pens).map(r=>`<tr><td>${r.date}</td><td>${esc(batchName(r.batch_id))}</td><td>${esc(r.pen)}</td><td>${fmt(r.count,0)}</td><td>${fmtWeight(r.total/r.count)}</td></tr>`))}</details>`;
}

function renderSettings(){
 renderWorkbookSources();
 $('#barn-settings').innerHTML=table(['barn','group','edit'],data.barns.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.group)}</td><td>${recordActions('barns',r)}</td></tr>`));
 $('#batch-settings').innerHTML=table(['barn','batch','entryDate','entry','age','status','edit'],data.batches.map(r=>`<tr><td>${esc(data.barns.find(x=>x.id===r.barn_id)?.name)}</td><td>${esc(r.name)}</td><td>${r.entry_date}</td><td>${fmt(r.entry_count,0)}</td><td>${fmt(r.entry_age_days)}</td><td>${esc(t(r.status))}</td><td>${recordActions('batches',r)}</td></tr>`));
 if(me.role==='admin'&&!document.activeElement?.closest('#user-results'))loadAdmin();
}
async function loadAdmin(){if(me?.role!=='admin')return;try{const [users,audit]=await Promise.all([api('/api/users'),api('/api/audit')]);if(!document.activeElement?.closest('#user-results'))$('#user-results').innerHTML=users.map(u=>`<div class="user-row" data-user="${u.id}"><span>${esc(u.username)}</span><select aria-label="${t('role')}">${['admin','staff','viewer'].map(k=>`<option value="${k}" ${u.role===k?'selected':''}>${t(k)}</option>`).join('')}</select><label class="check"><input type="checkbox" ${u.active?'checked':''}>${t('enabled')}</label><button data-update-user="${u.id}">${t('saveSettings')}</button><input type="password" autocomplete="new-password" minlength="4" maxlength="8" pattern="[0-9]{4,8}" inputmode="numeric" aria-label="${t('resetPassword')}" placeholder="${t('resetPassword')}"><input type="hidden" value="${esc(JSON.stringify({role:u.role,active:u.active,revision:u.revision}))}"></div>`).join('');preserveBox('audit-results',audit.map(a=>`<details data-key="audit-${a.seq}"><summary>${esc(a.timestamp)} · ${esc(a.username||a.user_id)} · ${esc(a.action)} / ${esc(a.kind)}</summary><p>${t('before')}</p><pre>${esc(a.before_value||'—')}</pre><p>${t('after')}</p><pre>${esc(a.after_value||'—')}</pre></details>`).join(''))}catch(e){toast(messageError(e))}}
async function refresh(){if(refreshing||!me)return;refreshing=true;try{const incoming=await api('/api/snapshot'+(data?.cursor?'?since='+encodeURIComponent(data.cursor):''));if(incoming.unchanged){if(navigator.onLine&&!registration?.waiting)$('#connection').hidden=true;return}data=incoming;if(data.version!==VERSION){$('#connection').textContent=t('update');$('#connection').hidden=false;return}selections();await renderCurrent();if(navigator.onLine&&!registration?.waiting)$('#connection').hidden=true}catch(e){$('#connection').textContent=t('syncError');$('#connection').hidden=false}finally{refreshing=false}}
function edit(kind,id){if(pending){toast(t('pending'));return}const r=data[kind].find(x=>x.id===id);const f=$(`form[data-kind=${kind}]`);const destination={movements:'daily',deliveries:'feed',usages:'feed',weights:'weights',barns:'settings',batches:'settings'}[kind];location.hash=destination;f.dataset.editId=id;f.dataset.revision=r.revision;f.querySelector('[data-action=cancelEdit]').hidden=false;f.querySelector('.edit-label').hidden=false;
 if(f.id==='movement-form')f.elements.outgoing_destination.value=r.outgoing_destination||'';
 if(r.batch_id){const b=data.batches.find(b=>b.id===r.batch_id);f.elements.barn_id.value=b.barn_id;updateScope(f.querySelector('.scope'));f.elements.batch_id.value=b.id}
 for(const [k,v] of Object.entries(r)){const el=f.elements.namedItem(k);if(el&&typeof v!=='object'){if(el.type==='checkbox')el.checked=v;else el.value=v??''}}
 if(kind==='deliveries'){f.elements.allocation_mode.value=r.allocations.length===0?'common':r.allocations.length===1?'single':'multiple';f.elements.amount.value=r.display_unit==='ton'?r.kg/1000:r.kg;f.dataset.unit=r.display_unit;$('#allocation-rows').replaceChildren();r.allocations.forEach(allocationRow);if(r.allocations.length===1){const b=data.batches.find(b=>b.id===r.allocations[0].batch_id);f.elements.barn_id.value=b.barn_id;updateScope(f.querySelector('.scope'));f.elements.batch_id.value=b.id}}
 if(kind==='weights'){f.elements.weight_mode.value=r.individual_kg.length?'individual':'total';f.elements.individual_kg.value=r.individual_kg.join(', ')}
 if(kind==='batches'){if(r.legacy_source){f.elements.entry_count.value=r.entry_count??'';f.elements.entry_count.readOnly=true;f.elements.entry_count.required=false;f.elements.entry_date.readOnly=true;}f.elements.entry_age.value=r.entry_age_days??'';f.elements.age_unit.value='days'}
 f.querySelectorAll('details').forEach(d=>d.open=true);conditional();f.scrollIntoView({behavior:'smooth',block:'center'});
}
function clickAction(e){const b=e.target.closest('button');if(!b)return;
 if(b.dataset.addBarn){const f=$('#movement-form');f.elements.barn_id.value=b.dataset.addBarn;updateScope(f.querySelector('.scope'),true);f.scrollIntoView({behavior:'smooth',block:'center'});return}
 if(b.dataset.edit){edit(b.dataset.edit,b.dataset.id);return}
 if(b.dataset.delete){deleteItem={kind:b.dataset.delete,id:b.dataset.id};$('#delete-dialog').showModal();return}
 if(b.dataset.export){download('/api/export?kind='+b.dataset.export+'&'+query($('#'+b.dataset.filter)));return}
 if(b.dataset.action==='cancelEdit'){finishForm(b.closest('form'));b.closest('form').querySelector('.form-error').textContent='';return}
 if(b.dataset.action==='clear'){const f=b.closest('form');f.reset();syncFilters(f);renderCurrent();return}
 if(b.dataset.downloadSource){download('/api/workbooks/'+b.dataset.downloadSource+'/file');return}
 if(b.dataset.updateUser){updateUser(b.closest('.user-row'));return}
}
async function download(path){try{const response=await fetch(path,{cache:'no-store'});if(!response.ok){throw await response.json()}const blob=await response.blob();const disposition=response.headers.get('Content-Disposition')||'';const name=disposition.match(/filename="([^"]+)"/)?.[1]||(disposition.includes("filename*=UTF-8''")?decodeURIComponent(disposition.split("filename*=UTF-8''")[1]):'pigledger-backup.json');const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(messageError(e))}}
async function importBackup(){const file=$('#import-file').files[0];if(!file)return;const b=$('#import-backup');b.disabled=true;try{const doc=JSON.parse(await file.text());const result=await api('/api/import',{method:'POST',body:JSON.stringify(doc)});$('#backup-result').textContent=`${t('saved')} · ${t('importedCount')}: ${result.added} / ${t('skippedCount')}: ${result.skipped}`;await refresh()}catch(e){$('#backup-result').textContent=messageError(e)}finally{b.disabled=false}}
let workbookDraft=null;
function workbookHTML(book){
 const {report,plan}=book;const total=report.totals;
 let html=`<p class="note">${esc(t('provisional'))} · ${esc(t('countsDate'))}: ${esc(plan.counts_as_of)} → ${esc(report.as_of)}</p><p>${t('sourceCumulative')} · ${t('entry')}: ${fmt(total.entry,0)} · ${t('remaining')}: ${fmt(total.remaining,0)} · ${t('sale')}: ${fmt(total.sold,0)} · ${t('cull')}: ${fmt(total.culled,0)} · ${t('dead')}: ${fmt(total.dead,0)}</p>`;
 const rows=[];
 for(const row of report.rows){const p=plan.rows.find(x=>x.key===row.key);for(const barn of row.barns)rows.push(`<tr><td>${barn} ${t('barn')}</td><td>${esc(row.name)}</td><td>${fmt(p.provided[barn],0)}</td><td>${fmt(p.before[barn],0)}</td><td>${fmt(p.current[barn],0)}</td><td>${esc(row.entry_date)}</td></tr>`)}
 html+=table(['barn','batch','countsText','previousHeads','currentHeads','entryDate'],rows);
 html+=`<p class="hint">${esc(t('legacyHint'))}</p>`;
 for(const row of report.rows){const p=plan.rows.find(x=>x.key===row.key);html+=`<details data-key="${book.id||book.sha256}-${row.key}"><summary>${esc(row.name)} · ${esc(row.barn_text)}</summary>${p.issues.includes('closed_barn_historical_date_unknown')?`<p class="note">${esc(t('historicalDateUnknown'))}</p>`:''}<p>${esc(t('mean'))} · ${esc(t('sourceExcel'))} (${esc(t('insufficient'))})</p>${row.weights.map(w=>`<p>${esc(w.date)} · ${fmt(w.mean_kg)} kg · ${esc(t('weightCount'))}: —</p>`).join('')}${Object.entries(row.comments).map(([cell,text])=>`<details data-key="source-${book.id||book.sha256}-${cell}"><summary>${esc(report.sheet)}!${esc(cell)}</summary><pre>${esc(text)}</pre></details>`).join('')}</details>`}
 return html;
}
function renderWorkbookSources(){
 if(!data)return;const books=data.workbooks||[];if(workbookDraft)preserveBox('workbook-preview',workbookHTML(workbookDraft.preview));
 preserveBox('workbook-sources',books.map(b=>`<details data-key="book-${b.id}" open><summary>${esc(b.filename)} · ${esc(b.report.as_of)}</summary><button data-download-source="${b.id}">${esc(t('originalFile'))}</button>${workbookHTML(b)}</details>`).join(''));
}
async function workbookPayload(){
 const f=$('#workbook-form'),file=$('#workbook-file').files[0];if(!file||file.size>8*1024*1024)throw {error:'invalid_workbook'};
 const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=8192)binary+=String.fromCharCode(...bytes.subarray(offset,offset+8192));
 return {filename:file.name,base64:btoa(binary),counts_as_of:val(f,'counts_as_of'),counts_text:val(f,'counts_text'),closed_barns:val(f,'closed_barns').split(/[,，\s]+/).filter(Boolean).map(Number),source_url:''};
}
async function previewWorkbook(event){
 event.preventDefault();const f=$('#workbook-form'),button=f.querySelector('[type=submit]');if(!f.reportValidity())return;button.disabled=true;$('#apply-workbook').disabled=true;
 try{const payload=await workbookPayload(),preview=await api('/api/workbook/preview',{method:'POST',body:JSON.stringify(payload)});workbookDraft={payload,preview,key:crypto.randomUUID(),user:me.id};$('#workbook-preview').innerHTML=workbookHTML(preview);f.querySelector('.form-error').textContent='';$('#apply-workbook').disabled=false}
 catch(e){f.querySelector('.form-error').textContent=messageError(e)}finally{button.disabled=false}
}
async function applyWorkbook(){
 if(!workbookDraft||workbookDraft.user!==me?.id)return;const button=$('#apply-workbook'),f=$('#workbook-form'),draft=workbookDraft;button.disabled=true;
 try{const result=await api('/api/workbook/import',{method:'POST',body:JSON.stringify(draft.payload),headers:{'Idempotency-Key':draft.key}});toast(t(result.already_imported?'workbookAlready':'saved'));f.querySelector('.form-error').textContent=t(result.already_imported?'workbookAlready':'saved');workbookDraft=null;delete f.dataset.dirty;$('#workbook-preview').replaceChildren();await refresh()}
 catch(e){f.querySelector('.form-error').textContent=messageError(e);button.disabled=false}
}
async function createUser(e){e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('/api/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});f.elements.username.value='';f.elements.password.value='';f.querySelector('.form-error').textContent='';toast(t('saved'));loadAdmin()}catch(e){f.querySelector('.form-error').textContent=messageError(e)}finally{b.disabled=false}}
async function updateUser(row){try{await api('/api/users/'+row.dataset.user,{method:'PUT',body:JSON.stringify({role:row.querySelector('select').value,active:row.querySelector('[type=checkbox]').checked,password:row.querySelector('[type=password]').value,before:JSON.parse(row.querySelector('[type=hidden]').value)})});toast(t('saved'));if(row.dataset.user===me.id){me=null;$('#workspace').hidden=true;$('#login-view').hidden=false}else loadAdmin()}catch(e){toast(messageError(e))}}
function restorePending(){
 if(!pending||pending.user!==me.id||!pending.formId)return;
 const f=$('#'+pending.formId);if(!f||f.dataset.pendingRestored===pending.key)return;
 const r=pending.body;f.dataset.pendingRestored=pending.key;
 if(f.id==='movement-form')f.elements.outgoing_destination.value=r.outgoing_destination||'';
 if(r.batch_id){const b=data.batches.find(b=>b.id===r.batch_id);if(b){f.elements.barn_id.value=b.barn_id;updateScope(f.querySelector('.scope'));const select=f.elements.batch_id;if(!Array.from(select.options).some(o=>o.value===b.id))select.add(new Option(b.name,b.id));select.value=b.id}}
 for(const [k,v] of Object.entries(r)){const el=f.elements.namedItem(k);if(el&&typeof v!=='object'){if(el.type==='checkbox')el.checked=v;else el.value=v??''}}
 if(f.id==='delivery-form'){f.elements.allocation_mode.value=r.allocations.length===0?'common':r.allocations.length===1?'single':'multiple';f.elements.amount.value=r.display_unit==='ton'?r.kg/1000:r.kg;f.dataset.unit=r.display_unit;$('#allocation-rows').replaceChildren();r.allocations.forEach(allocationRow);if(r.allocations.length===1){const b=data.batches.find(b=>b.id===r.allocations[0].batch_id);if(b){f.elements.barn_id.value=b.barn_id;updateScope(f.querySelector('.scope'));f.elements.batch_id.value=b.id}}}
 if(f.id==='weight-form'){f.elements.weight_mode.value=r.individual_kg?.length?'individual':'total';f.elements.individual_kg.value=(r.individual_kg||[]).join(', ')}
 if(f.id==='batch-form'){f.elements.entry_age.value=r.entry_age_days??'';f.elements.age_unit.value='days'}
 if(pending.method==='PUT'){f.dataset.editId=pending.path.split('/').pop();f.dataset.revision=r.revision;f.querySelector('[data-action=cancelEdit]').hidden=false;f.querySelector('.edit-label').hidden=false}
 conditional();persistPending();
}

async function enter(user){me=user;data=null;selectionFingerprint='';$('#login-view').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;$('#user-name').textContent=user.username+' · '+t(user.role);await refresh();$$('.filters').forEach(f=>{for(const k of ['from','to','barn_id'])if(sharedFilters[k])f.elements[k].value=sharedFilters[k];updateFilterBatch(f);if(sharedFilters.batch_id)f.elements.batch_id.value=sharedFilters.batch_id});await renderCurrent();restorePending();persistPending()}
function hasUnsavedWork(){return !!pending||!!$('#weighing-form')?.dataset.dirty||!!($('#delete-dialog')?.open&&$('#void-reason')?.value)||Array.from(document.querySelectorAll('#user-form input,#password-form input,#activation-form input,#workbook-file')).some(i=>i.value)||$$('form[data-kind]').some(f=>f.dataset.dirty||f.dataset.editId||['quantity','amount','total_kg','individual_kg','kg','opening'].some(k=>val(f,k)));}
let registration=null;
function boot(){
$('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const user=await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});f.elements.password.value='';f.querySelector('.form-error').textContent='';await enter(user)}catch(e){f.querySelector('.form-error').textContent=messageError(e)}finally{b.disabled=false}};
$('#logout').onclick=async()=>{try{await api('/api/logout',{method:'POST',body:'{}'})}catch(e){toast(messageError(e));return}me=null;data=null;document.dispatchEvent(new Event('pigledger:logout'));$('#workspace').hidden=true;$('#login-view').hidden=false;$('#logout').hidden=true;$('#user-name').textContent='';};
$('#language').onchange=e=>{lang=e.target.value;localStorage.setItem('pig-language',lang);translate();if(data){selections(true);renderCurrent()}$('#user-name').textContent=me?me.username+' · '+t(me.role):''};
$('#retry').onclick=retryPending;
$('#cancel-delete').onclick=()=>$('#delete-dialog').close();
$('#confirm-delete').onclick=()=>{const r=data[deleteItem.kind].find(r=>r.id===deleteItem.id);$('#delete-dialog').close();startWrite('/api/'+deleteItem.kind+'/'+r.id,'DELETE',{revision:r.revision})};
window.addEventListener('hashchange',()=>setPage(location.hash.slice(1)));
window.addEventListener('offline',()=>{$('#connection').textContent=t('offline');$('#connection').hidden=false});
window.addEventListener('online',()=>refresh());
registration=null;
if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(r=>{registration=r;const prompt=()=>{if(r.waiting){$('#pwa-update').hidden=false;$('#connection').textContent=t('update');$('#connection').hidden=false}};prompt();r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',prompt));$('#pwa-update').onclick=()=>{if(hasUnsavedWork()){toast(t('pending'));return}if(r.waiting)r.waiting.postMessage('activate');else location.reload()};navigator.serviceWorker.addEventListener('controllerchange',()=>{if(registration?.active&&navigator.serviceWorker.controller&&sessionStorage.getItem('pig-sw-ready')){if(hasUnsavedWork()){$('#pwa-update').hidden=false;toast(t('pending'));}else location.reload();}sessionStorage.setItem('pig-sw-ready','1')})}).catch(()=>{});}
try{pending=JSON.parse(localStorage.getItem('pig-pending')||'null')}catch(e){}
build();translate();setPage(location.hash.slice(1),false);persistPending();
api('/api/me').then(enter).catch(()=>{});
setInterval(()=>{if(!document.hidden&&me)refresh()},15000);

}
